(()=>{
  const dashboard=document.querySelector('#adminDashboard');const overview=document.createElement('div');overview.append(...dashboard.children);dashboard.append(overview);
  const nav=document.createElement('div');nav.className='agent-periods';nav.setAttribute('aria-label','Tab admin');const panel=document.createElement('section');panel.hidden=true;const cases=document.createElement('section');cases.id='adminCasesPanel';cases.hidden=true;dashboard.prepend(nav);dashboard.append(panel,cases);let page=1;
  const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
  const btn=(text,run)=>{const b=el('button',text);b.type='button';b.className='secondary-action';b.onclick=run;return b;};
  const a=btn('Dashboard',()=>show(false)),b=btn('Urus Ejen',()=>{show(true);load();});nav.append(a,b);
  function show(manage){cases.hidden=true;overview.hidden=manage;panel.hidden=!manage;a.setAttribute('aria-pressed',String(!manage));b.setAttribute('aria-pressed',String(manage));}show(false);
  const mobile=matchMedia('(max-width:700px)'),floating=el('nav');floating.className='admin-floating-tabs';floating.setAttribute('aria-label','Navigasi admin');
  const sections=[overview.children[0],overview.children[1]],announcements=el('section');announcements.append(...Array.from(overview.children).slice(2));overview.append(announcements);sections.push(announcements,panel,cases);
  const tabs=[['Database','users'],['Trafik','chart-no-axes-combined'],['Hebahan','megaphone'],['Ejen','contact'],['Case','folder-open']];let selected=0;
  const caseTab=btn('Case',()=>select(4));nav.append(caseTab);
  tabs.forEach(([label,icon],index)=>{const button=btn('',()=>select(index));button.setAttribute('aria-label',label);const symbol=el('i');symbol.dataset.lucide=icon;button.append(symbol,el('span',label));floating.append(button);});dashboard.append(floating);window.lucide?.createIcons();
  a.onclick=()=>{selected=0;show(false);caseTab.setAttribute('aria-pressed','false');};b.onclick=()=>{selected=3;show(true);caseTab.setAttribute('aria-pressed','false');load();};
  function select(index){const changed=selected!==index;selected=index;applyTabs();if(index===3&&(changed||!panel.childElementCount))load();if(index===4)dispatchEvent(new Event('carloan-admin-case-open'));floating.classList.remove('is-scroll-hidden');floating.inert=false;}
  function applyTabs(){if(mobile.matches){overview.hidden=false;sections.forEach((section,index)=>{section.hidden=index!==selected;});}else if(selected===4){overview.hidden=true;panel.hidden=true;cases.hidden=false;a.setAttribute('aria-pressed','false');b.setAttribute('aria-pressed','false');}else{sections.slice(0,3).forEach(section=>section.hidden=false);show(selected===3);}caseTab.setAttribute('aria-pressed',String(selected===4));Array.from(floating.children).forEach((button,index)=>button.setAttribute('aria-current',index===selected?'page':'false'));}
  mobile.addEventListener('change',applyTabs);applyTabs();
  let lastY=scrollY,travel=0,direction=0;
  addEventListener('scroll',()=>{const y=Math.max(0,Math.min(scrollY,document.documentElement.scrollHeight-innerHeight)),delta=y-lastY;lastY=y;if(!mobile.matches||dashboard.hidden||document.querySelector('dialog[open]'))return;const next=Math.sign(delta);if(next!==direction){travel=0;direction=next;}travel+=Math.abs(delta);if(y<32||next<0&&travel>10){floating.classList.remove('is-scroll-hidden');floating.inert=false;}else if(next>0&&travel>24&&!floating.matches(':focus-within')){floating.classList.add('is-scroll-hidden');floating.inert=true;}},{passive:true});
  let dragging=false,suppressClick=false;
  floating.addEventListener('click',event=>{if(suppressClick){event.preventDefault();event.stopImmediatePropagation();suppressClick=false;}},true);
  function point(event){const button=document.elementFromPoint(event.clientX,event.clientY)?.closest('.admin-floating-tabs button');if(button){const index=Array.from(floating.children).indexOf(button);if(index>=0){Array.from(floating.children).forEach((item,i)=>item.classList.toggle('is-drag-target',i===index));return index;}}return -1;}
  floating.addEventListener('pointerdown',event=>{if(event.button!==0)return;dragging=true;floating.setPointerCapture(event.pointerId);point(event);});
  floating.addEventListener('pointermove',event=>{if(dragging)point(event);});
  floating.addEventListener('pointerup',event=>{if(!dragging)return;dragging=false;suppressClick=true;setTimeout(()=>{suppressClick=false;},0);const index=point(event);Array.from(floating.children).forEach(item=>item.classList.remove('is-drag-target'));if(index>=0)select(index);});
  floating.addEventListener('pointercancel',()=>{dragging=false;Array.from(floating.children).forEach(item=>item.classList.remove('is-drag-target'));});
  async function api(action,body){const r=await fetch('/api/app?action=manage-agent-'+action+(body?'':'&page='+page),{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store'});const data=await r.json();if(!r.ok)throw new Error(data.error||'Sambungan gagal.');return data;}
  let listGeneration=0,lastAgentSignature='';
  addEventListener('carloan-admin-live',()=>{if(!dashboard.hidden&&!panel.hidden&&!document.querySelector('dialog[open]'))load(true);});
  async function load(quiet=false){const version=++listGeneration;if(!quiet)panel.replaceChildren(el('p','Memuatkan ejen...'));try{const data=await api('list');if(version!==listGeneration)return;const signature=JSON.stringify([page,data]);if(quiet&&signature===lastAgentSignature)return;lastAgentSignature=signature;panel.replaceChildren();const top=el('div');top.className='analytics-heading';top.append(el('h2','Urus Ejen'),btn('+ Daftar Ejen',()=>edit()));panel.append(top);for(const row of data.records){const card=el('article');card.className='managed-agent';card.append(el('h3',row.name),el('p',row.email),el('p',row.phone),el('small',row.disabled?'Dinyahaktifkan':row.confirmed?'Email disahkan':'Menunggu pengesahan email'));const actions=el('div');actions.className='analytics-heading';actions.append(btn('Edit',()=>edit(row)));if(!row.disabled)actions.append(btn('Delete',()=>remove(row)));card.append(actions);panel.append(card);}if(!data.records.length)panel.append(el('p','Tiada ejen PRO pada halaman ini.'));const paging=el('div');paging.className='analytics-heading';const prev=btn('Sebelum',()=>{page--;load();}),next=btn('Seterusnya',()=>{page++;load();});prev.disabled=page===1;next.disabled=!data.hasNext;paging.append(prev,el('span','Halaman '+page),next);panel.append(paging);}catch(error){if(version!==listGeneration||quiet)return;panel.replaceChildren(el('p',error.message),btn('Cuba semula',()=>load()));}}
  function modal(title){const d=el('dialog');d.className='app-dialog';const top=el('div');top.className='analytics-heading';top.append(el('h2',title),btn('Tutup',()=>d.close()));d.append(top);document.body.append(d);d.addEventListener('close',()=>d.remove());return d;}
  function edit(row){const d=modal(row?'Edit Ejen':'Daftar Ejen'),f=el('form');for(const [key,title,type]of[['name','Nama','text'],['phone','No WhatsApp','tel'],['email','Email','email'],...(!row?[['password','Password','password']]:[])]){const label=el('label',title),input=el('input');input.name=key;input.type=type;input.required=true;input.value=row?.[key]||'';input.maxLength=key==='name'?100:key==='phone'?20:key==='email'?254:256;if(key==='password'){input.minLength=8;input.autocomplete='new-password';}if(key==='email'&&row)input.readOnly=true;label.append(input);f.append(label);}const feedback=el('p');feedback.setAttribute('role','status');const save=btn('Simpan');save.type='submit';f.append(feedback,save);d.append(f);f.onsubmit=async event=>{event.preventDefault();save.disabled=true;try{await api(row?'edit':'create',{...Object.fromEntries(new FormData(f)),...(row?{id:row.id}:{})});if(!row){f.reset();feedback.textContent='Akaun berjaya didaftarkan. Ejen boleh terus login.';}else{d.close();await load();}}catch(error){feedback.textContent=error.message;}finally{save.disabled=false;}};d.showModal();}
  function remove(row){const d=modal('Delete Ejen');d.append(el('p','Nyahaktifkan '+row.name+'? Akses PRO disekat. Case, appointment dan rekod admin dikekalkan.'));const first=btn('Teruskan',()=>{first.remove();const label=el('label','Pengesahan kedua: taip email ejen'),input=el('input');input.type='email';label.append(input);const feedback=el('p');feedback.setAttribute('role','status');const confirm=btn('Sahkan Delete',async()=>{if(input.value!==row.email){feedback.textContent='Email tidak sepadan.';return;}confirm.disabled=true;try{await api('delete',{id:row.id,confirm:true,confirmEmail:input.value});d.close();load();}catch(error){feedback.textContent=error.message;confirm.disabled=false;}});d.append(label,feedback,confirm);});d.append(first);d.showModal();}
})();
